/* From Uiverse.io by Remon125 - Tags: button, smooth button */
.__UIV_SCOPE__ button {
  padding: 15px 60px;
  background: transparent;
  border: 2px solid #6528F7;
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  border-radius: 6px;
  cursor: pointer;
  position: relative;
  display: flex;
  overflow: hidden;
  transition: all 0.5s;
  text-transform: uppercase;
}

.__UIV_SCOPE__ button span {
  transition: all 0.5s;
  z-index: -1;
}

.__UIV_SCOPE__ button::after,
.__UIV_SCOPE__ button::before {
  content: "";
  position: absolute;
  width: 0;
  height: 100%;
  background: #6528F7;
  top: 0;
  transform: skewX(35deg);
  transition: all 0.5s;
  z-index: -1;
}

.__UIV_SCOPE__ button::after {
  left: -20px;
}

.__UIV_SCOPE__ button::before {
  right: -20px;
}

.__UIV_SCOPE__ button:hover::after {
  width: 50%;
  left: 0;
}

.__UIV_SCOPE__ button:hover::before {
  width: 50%;
  right: 0;
}
